const size = ["sm", "md", "lg"] as const;

export { size as inputSizes };

export default {
  slots: {
    wrapper:
      "relative inline-flex w-full items-center gap-3 rounded-full bg-gray-2 text-gray-8 transition-colors ring-1 ring-transparent focus-within:bg-white focus-within:ring-gray-8/20 data-[filled=true]:bg-white data-[disabled=true]:bg-gray-3 data-[disabled=true]:text-gray-5",
    input:
      "min-w-0 flex-1 bg-transparent text-gray-8 placeholder:text-gray-5 outline-none disabled:cursor-not-allowed",
    leading: "inline-flex items-center text-gray-6",
    trailing: "inline-flex items-center text-gray-6",
  },
  variants: {
    fieldGroup: {
      horizontal:
        "not-only:first:rounded-e-none not-only:last:rounded-s-none not-last:not-first:rounded-none focus-within:z-[1]",
      vertical:
        "not-only:first:rounded-b-none not-only:last:rounded-t-none not-last:not-first:rounded-none focus-within:z-[1]",
    },
    size: {
      sm: {
        wrapper: "h-[var(--input-sm-height)] px-4 text-[length:var(--text-size-26)] leading-[1.5]",
        input: "text-[length:var(--text-size-26)] leading-[1.5]",
      },
      md: {
        wrapper: "h-[var(--input-md-height)] px-5 text-[length:var(--text-size-28)] leading-[1.5]",
        input: "text-[length:var(--text-size-28)] leading-[1.5]",
      },
      lg: {
        wrapper: "h-[var(--input-lg-height)] px-6 text-[length:var(--text-size-32)] leading-[1.5]",
        input: "text-[length:var(--text-size-32)] leading-[1.5]",
      },
    },
    multiline: {
      true: {
        wrapper: "h-auto items-start rounded-2xl py-4",
        input: "min-h-[160px] resize-none",
      },
    },
  },
  defaultVariants: {
    size: "md" as (typeof size)[number],
  },
};

const inputSizes = ["sm", "md", "lg"] as const;

const config = {
  slots: {
    wrapper: "relative flex w-full items-center",
    input:
      "flex h-10 w-full rounded-md border border-gray-2 bg-gray-2 px-3  text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
    leading: "absolute left-3 top-0 bottom-0 flex items-center justify-center text-muted-foreground",
    trailing: "absolute right-3 top-0 bottom-0 flex items-center justify-center text-muted-foreground",
    // Styles for internal icons like clear and password toggle
    icon: "absolute right-3 top-0 bottom-0 flex items-center justify-center text-muted-foreground transition-opacity hover:opacity-80 cursor-pointer z-10",
  },
  variants: {
    size: {
      sm: {
        input: "h-input-sm px-3",
      },
      md: {
        input: "h-input-md px-3",
      },
      lg: {
        input: "h-input-lg px-8 rounded-md",
      },
    },
    multiline: {
      true: {
        input: "h-auto",
      },
    },
    fieldGroup: {
      horizontal: {
        wrapper: "first:rounded-r-none last:rounded-l-none",
        input: "first:rounded-r-none last:rounded-l-none focus:z-10",
      },
      vertical: {
        wrapper: "first:rounded-b-none last:rounded-t-none",
        input: "first:rounded-b-none last:rounded-t-none focus:z-10",
      },
    },
    hasLeading: {
      true: {
        input: "pl-9",
      },
    },
    hasTrailing: {
      true: {
        input: "pr-9",
      },
    },
    rounded: {
      true: {
        input: "rounded-full",
      },
      false: {
        input: "rounded-md",
      },
    },
  },
  defaultVariants: {
    size: "md",
    rounded: true,
  },
} as const;

export { inputSizes };
export default config;
